CREATE DEFINER=`root`@`localhost` PROCEDURE `gen_daily_report`(
username NVARCHAR(50),
tradedate NVARCHAR(50)
)
BEGIN
select distinct @startamount := first_value(buy_amount) over (order by order_seq_id asc) as invest_amount, @endamount := (first_value(buy_amount) over (order by order_seq_id asc) + sum(profit_amount) - sum(commission_price)) as final_amount from `ant_cryptotradingbot_v2`.`order_report` where username = username and sell_amount is not null and update_date >= tradedate and update_date <= concat(tradedate, ' 23:59:59');
set @profitamount = @endamount - @startamount;
set @profitpercent = (@endamount - @startamount) / (@startamount / 100);
INSERT `ant_cryptotradingbot_v2`.`daily_profit_report` (`date`, `username`, `start_amount`, `end_amount`, `profit_amount`, `profit_percent`, `update_date`) VALUES (tradedate, username, @startamount, @endamount, @profitamount, @profitpercent, concat(tradedate, ' 23:59:59'));
END ;;
DELIMITER ;
