CREATE DEFINER=`root`@`localhost` PROCEDURE `order_reports`(
username NVARCHAR(50),
fromDate NVARCHAR(50),
toDate NVARCHAR(50)
)
BEGIN
select `date`, symbol, symbolname, `type`, quantity, avg_price, order_value, `status` from (
select distinct bcsd.order_date as 'date', bcsn.symbol_name as symbol, replace(bcsn.symbol_full_name, '_', '') as symbolname, 'Buy' as 'type', FLOOR(bcsd.order_quantity) as quantity, bcsd.buy_price as avg_price, bcsd.buy_amount as order_value, 'Successful' as 'status' from `ant_cryptotradingbot_v2`.`order_report`  as bcsd
inner join `ant_cryptotradingbot_v2`.`crypto_symbols_name` as bcsn on bcsn.symbol_name = replace(bcsd.symbol_name, 'USDT', '')
where bcsd.username = username and (bcsd.order_date >= fromDate or fromDate = '') and (bcsd.order_date <= toDate or toDate = '')
union all
select distinct bcsd.order_date as 'date', bcsn.symbol_name as symbol, replace(bcsn.symbol_full_name, '_', '') as symbolname, 'Buy' as 'type', FLOOR(bcsd.order_quantity) as quantity, bcsd.buy_price as avg_price, (bcsd.order_quantity*bcsd.buy_price) as order_value, 'Pending' as 'status' from `ant_cryptotradingbot_v2`.`current_buy_order_report`  as bcsd
inner join `ant_cryptotradingbot_v2`.`crypto_symbols_name` as bcsn on bcsn.symbol_name = replace(bcsd.symbol_name, 'USDT', '')
left join `ant_cryptotradingbot_v2`.`order_report`  as bcor on bcsd.symbol_name = bcor.symbol_name and bcsd.signal_type = bcor.signal_type and bcsd.order_quantity = bcor.order_quantity and bcsd.username = bcor.username and bcsd.order_date = bcor.order_date  
where bcsd.username = username and (bcsd.order_date >= fromDate or fromDate = '') and (bcsd.order_date <= toDate or toDate = '') and bcor.buy_price is null
union all
select distinct csd.sell_orderDate as 'date', csn.symbol_name as symbol, replace(csn.symbol_full_name, '_', '') as symbolname, 'Sell' as 'type', FLOOR(csd.order_quantity) as quantity, ifnull(cor.sell_price, 0) as avg_price, (csd.order_quantity*ifnull(cor.sell_price, 0)) as order_value, 'Pending' as 'status' from `ant_cryptotradingbot_v2`.`current_buy_order_report`  as csd
inner join `ant_cryptotradingbot_v2`.`crypto_symbols_name` as csn on csn.symbol_name = replace(csd.symbol_name, 'USDT', '')
left join `ant_cryptotradingbot_v2`.`order_report`  as cor on csd.symbol_name = cor.symbol_name and csd.signal_type = cor.signal_type and csd.order_quantity = cor.order_quantity  and csd.username = cor.username and csd.order_date = cor.order_date  
where csd.username = username and (csd.sell_orderDate >= fromDate or fromDate = '') and (csd.sell_orderDate <= toDate or toDate = '') and cor.sell_price is not null and csd.sell_orderDate is not null
union all
select distinct csd.update_date as 'date', csn.symbol_name as symbol, replace(csn.symbol_full_name, '_', '') as symbolname, 'Sell' as 'type', FLOOR(csd.order_quantity) as quantity, csd.sell_price as avg_price, csd.sell_amount as order_value, 'Successful' as 'status' from `ant_cryptotradingbot_v2`.`order_report`  as csd
inner join `ant_cryptotradingbot_v2`.`crypto_symbols_name` as csn on csn.symbol_name = replace(csd.symbol_name, 'USDT', '')
where csd.username = username and (csd.update_date >= fromDate or fromDate = '') and (csd.update_date <= toDate or toDate = '') and csd.update_date is not null
order by `date` desc) as cte;

END ;;
DELIMITER ;
